from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    groups = []
    current_group = ''
    depth = 0
    for character in paren_string:
        if character == ' ':
            continue
        current_group += character
        if character == '(':
            depth += 1
        elif character == ')':
            depth -= 1
        if depth == 0 and current_group:
            groups.append(current_group)
            current_group = ''
    return groups

