def reverse_vowels(str1):
    vowels = 'aeiouAEIOU'
    characters = list(str1)
    left_index = 0
    right_index = len(characters) - 1
    while left_index < right_index:
        if characters[left_index] not in vowels:
            left_index += 1
        elif characters[right_index] not in vowels:
            right_index -= 1
        else:
            characters[left_index], characters[right_index] = characters[right_index], characters[left_index]
            left_index += 1
            right_index -= 1
    return ''.join(characters)

